package com.subhamviky.settlement.generated;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.Supplier;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.slf4j.MDC;

/**
 * settlement-service — observability module (generated by A2C CodeGenAgent).
 * Correlation id in the logging MDC, in-process counters and latency samples,
 * and a p95 SLO check. Platform exporters read from this class.
 */
public final class Observability {

    public static final String CORRELATION_ID = "correlationId";
    private static final Logger logger = LoggerFactory.getLogger("settlement-service");
    private static final Map<String, AtomicLong> COUNTERS = new ConcurrentHashMap<>();
    private static final Map<String, List<Double>> LATENCIES_MS = new ConcurrentHashMap<>();

    private Observability() {
    }

    /** Time an operation, count success or error, and log the outcome. */
    public static <T> T traced(String operation, Supplier<T> action) {
        if (MDC.get(CORRELATION_ID) == null) {
            MDC.put(CORRELATION_ID, UUID.randomUUID().toString());
        }
        long start = System.nanoTime();
        try {
            T result = action.get();
            increment(operation + ".success");
            return result;
        } catch (RuntimeException e) {
            increment(operation + ".error");
            logger.error("operation failed: {}", operation, e);
            throw e;
        } finally {
            double millis = (System.nanoTime() - start) / 1_000_000.0;
            LATENCIES_MS.computeIfAbsent(operation, k -> Collections.synchronizedList(new ArrayList<>()))
                    .add(millis);
            logger.info("operation finished: {} in {} ms", operation, String.format("%.2f", millis));
        }
    }

    public static void increment(String counter) {
        COUNTERS.computeIfAbsent(counter, k -> new AtomicLong()).incrementAndGet();
    }

    public static long count(String counter) {
        AtomicLong value = COUNTERS.get(counter);
        return value == null ? 0 : value.get();
    }

    public static double p95(String operation) {
        List<Double> samples = new ArrayList<>(LATENCIES_MS.getOrDefault(operation, List.of()));
        if (samples.isEmpty()) {
            return 0.0;
        }
        Collections.sort(samples);
        int index = (int) Math.round(0.95 * (samples.size() - 1));
        return samples.get(Math.min(samples.size() - 1, index));
    }

    /** p95 latency objective for one operation. */
    public static boolean sloMet(String operation, double p95TargetMs) {
        return p95(operation) <= p95TargetMs;
    }
}
